def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    rich_aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('budget', 0) >= 400 and opp.get('hp', 0) >= 6:
                rich_aggressive += 1

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.45

    if day >= 8:
        urgency += 0.2

    if supply >= 23:
        base = 8.0
    elif supply >= 21:
        base = 14.0
    elif supply >= 19:
        base = 24.0
    elif supply >= 17:
        base = 42.0
    else:
        base = 68.0

    if highest_prev >= 180:
        pressure_bid = 0.0
    elif highest_prev >= 140:
        pressure_bid = min(highest_prev + 3.0, 120.0)
    elif highest_prev > 0:
        pressure_bid = highest_prev + 2.0
    else:
        pressure_bid = 35.0

    bid = max(base, pressure_bid * (0.35 + 0.45 * scarcity))

    if rich_aggressive >= 2 and urgency < 0.9 and supply >= 19:
        bid *= 0.55

    if urgency >= 1.8:
        bid = max(bid, 135.0 + 25.0 * scarcity)
    elif urgency >= 1.0:
        bid = max(bid, 85.0 + 20.0 * scarcity)

    reserve = 0.0
    if hp > 4 and day <= 7:
        reserve = 35.0
    cap = max(0.0, budget - reserve)
    if urgency >= 1.0:
        cap = budget

    bid = min(bid, cap)
    bid = max(0.0, bid)

    if budget < 25:
        bid = budget

    return float(round(bid, 2))

